/**
 * Phase 51.I — Recurring Jobs admin.
 * Endpoints:
 *   GET    /api/recurring-jobs
 *   POST   /api/recurring-jobs
 *   PATCH  /api/recurring-jobs/{id}
 *   DELETE /api/recurring-jobs/{id}
 *   POST   /api/recurring-jobs/{id}/generate?through=YYYY-MM-DD
 */
import React, { useEffect, useState, useMemo, useRef } from "react";
import { useSearchParams } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { CalendarClock, Plus, Pause, Play, Trash2, RefreshCw, X, Ban, Sparkles, Search, MoreVertical, Pencil, Tag } from "lucide-react";
import { toast } from "sonner";
import { api } from "@/api";
import { colors } from "@/theme";
import { usePermissions } from "@/hooks/usePermissions";
import {
  MonthlyNthWeekdaySelector,
} from "@/components/recurring/MonthlyNthWeekdaySelector";
import CustomerCombobox from "@/components/customers/CustomerCombobox";
import CategoryComboCell from "@/components/recurring/CategoryComboCell";
import MasterServiceCombobox from "@/components/services/MasterServiceCombobox";
import { CustomerLink, PhoneLink } from "@/components/customer";
// Task E · Feb-2026 — Shared navy filter/search strip primitive.
import NavyFilterBar from "@/components/ui/NavyFilterBar";

const FREQ_OPTIONS = [
  { value: "weekly", label: "Weekly" },
  { value: "biweekly", label: "Bi-weekly" },
  { value: "monthly", label: "Monthly" },
  { value: "quarterly", label: "Quarterly (every 3 months)" },
  { value: "semi_annual", label: "Semi-annual (every 6 months)" },
  { value: "custom", label: "Custom (every N days)" },
];
const DOW = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

function fmtMoney(cents) { return `$${(Number(cents || 0) / 100).toFixed(2)}`; }
function todayIso() { return new Date().toISOString().slice(0, 10); }
function addDaysIso(iso, days) {
  const d = new Date(iso + "T00:00:00");
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}

export default function RecurringJobs() {
  const { t } = useTranslation("propertyselector");
  // Phase P3 · Feb-2026 — Destructive-action gate for the 3-dot
  // Actions menu (Edit / Pause-Resume / Delete permanently).
  // Delete permanently is admin-only; the rest of the menu is
  // available to every role the page already renders for.
  const { role } = usePermissions();
  const canHardDelete = role === "admin" || role === "super_admin";
  const [items, setItems] = useState([]);
  // ── Phase P18 · Feb-2026 · Active / Paused tab switcher ──────────
  // Selected tab persists in the URL query (``?status=active`` |
  // ``?status=paused``) so refresh + deep links land on the right
  // tab.  Counts come from the backend so the badge reflects the
  // TENANT-wide count, not just the current filtered page.
  const [searchParams, setSearchParams] = useSearchParams();
  const _initialStatus = (() => {
    const raw = (searchParams.get("status") || "").toLowerCase();
    return raw === "paused" ? "paused" : "active";
  })();
  const [statusTab, setStatusTab] = useState(_initialStatus);
  const [tabCounts, setTabCounts] = useState({
    active: 0, paused: 0, total: 0,
  });
  const [customers, setCustomers] = useState([]);
  const [techs, setTechs] = useState([]);
  // Phase H9 · Feb-2026 — load crews for the combined "Assigned
  // to" dropdown. Falls back to an empty list if the endpoint
  // 403s (tech role) so the modal still renders.
  const [crews, setCrews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  // Phase H9 · Feb-2026 — user-facing price string. Kept
  // separate from ``editing.price_cents`` so the input is
  // freely typable (backspace / select-all / partial decimals)
  // WITHOUT round-tripping through Number() on every keystroke.
  const [priceStr, setPriceStr] = useState("0.00");
  const [priceErr, setPriceErr] = useState("");
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(null);
  // Feb-2026 · Recurring Jobs · hard-delete confirmation modal.
  // Kept OUT of the row's own state so the modal survives a row
  // re-render (busy flag flips as soon as the confirm click
  // fires) — the confirmation is a distinct destructive action
  // gated behind its own explicit confirm button.
  const [hardDeleteTarget, setHardDeleteTarget] = useState(null);
  // Phase R1 · Feb-2026 — Bulk Hard Delete state.
  //   ``selectedIds``: Set<string> of the checked rows across the
  //     currently-visible page.  Cleared after a successful bulk.
  //   ``bulkModalOpen``: gates the confirmation popup.
  //   ``bulkAcked``: user MUST tick the acknowledgement checkbox
  //     before the red "Permanently Delete" button becomes
  //     enabled — no type-to-confirm.
  //   ``bulkBusy``: prevents double-submits + drives the button's
  //     visual busy state during the network round-trip.
  const [selectedIds, setSelectedIds] = useState(() => new Set());
  const [bulkModalOpen, setBulkModalOpen] = useState(false);
  const [bulkAcked, setBulkAcked] = useState(false);
  const [bulkBusy, setBulkBusy] = useState(false);
  // Feb-2026 · P1 Auto-Activate + Bulk Activate — separate busy flag
  // so the "Bulk Activate" toolbar button gates on its own in-flight
  // state independently of the destructive "Delete permanently" flow.
  const [bulkActivateBusy, setBulkActivateBusy] = useState(false);
  // Phase P54 · Feb-2026 — Bulk-Edit-Categories modal state.
  //   ``bulkEditOpen``       — gate the modal.
  //   ``bulkEditServiceCat`` / ``bulkEditIncomeCat`` —
  //     dropdown value; empty string ``""`` is the "Unchanged"
  //     sentinel (do NOT send in the POST payload — the handler
  //     omits fields whose value is empty so the backend's
  //     ``model_fields_set`` check keeps them out of the write).
  //   ``bulkEditBusy``       — Apply-button spinner + double-submit
  //     guard.
  //   ``bulkEditError``      — inline error string (payload-level
  //     422 codes rendered next to the offending dropdown).
  const [bulkEditOpen, setBulkEditOpen] = useState(false);
  const [bulkEditServiceCat, setBulkEditServiceCat] = useState("");
  const [bulkEditIncomeCat, setBulkEditIncomeCat] = useState("");
  const [bulkEditBusy, setBulkEditBusy] = useState(false);
  const [bulkEditError, setBulkEditError] = useState("");
  // Feb-2026 P0 · Orphan-backfill state. Populated lazily on mount
  // so operators see a "Missing N template(s)" banner without
  // running the mutating backfill first.
  const [orphanPreview, setOrphanPreview] = useState(null);
  const [orphanBusy, setOrphanBusy] = useState(false);
  // Phase P14 · Feb-2026 · Item 2 — orphan-PURGE state (distinct
  // from the orphan-backfill above). ``purgePreview`` populated
  // by the ``/recurring-jobs/purge-orphans-preview`` scan; > 0
  // means there are ``recurring_job_templates`` rows whose
  // ``customer_id`` no longer resolves. ``purgeConfirmOpen``
  // gates the DELETE-typing confirm dialog; ``purgeInput`` is
  // the user's typed string that must match ``DELETE`` before
  // the POST fires. ``purgeBusy`` shows the button spinner.
  const [purgePreview, setPurgePreview] = useState(null);
  const [purgeConfirmOpen, setPurgeConfirmOpen] = useState(false);
  const [purgeInput, setPurgeInput] = useState("");
  const [purgeBusy, setPurgeBusy] = useState(false);
  // Phase P4 · Feb-2026 — Category taxonomy dropdowns on the
  // Edit Recurring Job modal.
  //   ``serviceCats`` / ``incomeCats``: tenant-scoped active
  //       rows fetched on modal open. Empty array is the natural
  //       "no rows in this tenant" signal → disabled dropdown.
  //   ``catLoadErr``: per-endpoint fetch failure so one broken
  //       list doesn't hide the other dropdown. Values are
  //       ``"service" | "income"`` mapped to a boolean.
  //   ``catSaveErr``: per-field 422 shape from PATCH so the user
  //       gets an inline error next to the offending dropdown
  //       and the modal stays open.
  const [serviceCats, setServiceCats] = useState([]);
  const [incomeCats, setIncomeCats] = useState([]);
  const [catLoadErr, setCatLoadErr] = useState({
    service: false, income: false,
  });
  const [catSaveErr, setCatSaveErr] = useState({
    service: "", income: "",
  });
  const [catLoading, setCatLoading] = useState(false);
  // Phase P33 · Feb-2026 — Property-selector state for the
  // create/edit modal. Mirrors the Least-Click pattern from
  // JobNew.jsx: fetch active properties on customer pick, then
  // branch on count:
  //   * 0  → inline "no addresses on file" warning; Save disabled.
  //   * 1  → auto-select the one property + read-only label; no
  //          dropdown affordance.
  //   * 2+ → required <select>; Save disabled until a pick.
  // ``propsLoading`` gates a subtle "Loading…" caption so the
  // absence of the picker on a slow customer switch doesn't read
  // as "no properties on this customer".
  const [customerProperties, setCustomerProperties] = useState([]);
  const [propsLoading, setPropsLoading] = useState(false);
  const previousModalCustomerRef = useRef(null);
  // Phase R2 · Feb-2026 — customer search.  Client-side filter.
  //   ``searchInput``: what the user is typing (unthrottled).
  //   ``searchQuery``: debounced value (250ms) used for filtering.
  const [searchInput, setSearchInput] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  useEffect(() => {
    const t = setTimeout(() => setSearchQuery(searchInput.trim().toLowerCase()), 250);
    return () => clearTimeout(t);
  }, [searchInput]);
  // Phase P54 · Feb-2026 — Service-category filter dropdown state.
  //   Empty string ``""`` is the "All categories" sentinel (default).
  //   Any non-empty value is an ``id`` matched against
  //   ``row.service_category_id`` in the ``filteredItems`` memo.
  //   The dropdown's <option> list comes from the same
  //   ``serviceCats`` state already populated by ``_loadCategories``
  //   (which now also fires on mount — see the useEffect right
  //   below the definition — so the filter has data before the
  //   Edit modal is ever opened).
  const [serviceCategoryFilter, setServiceCategoryFilter] = useState("");
  // Filtered view — kept as a memo so ``_visibleIds`` and the
  // table render share the exact same result set (bulk-select "on
  // page" must scope to the filtered rows, not the raw list).
  const filteredItems = useMemo(() => {
    let vis = items;
    if (searchQuery) {
      vis = vis.filter((r) => {
        const hay = [
          r.customer_name, r.customer_company_name,
          r.customer_email, r.customer_phone,
        ].filter(Boolean).join(" ").toLowerCase();
        return hay.includes(searchQuery);
      });
    }
    if (serviceCategoryFilter) {
      // P54 · exact-match filter on service_category_id. Rows with
      // no denorm still hit the "All categories" bucket (default);
      // an explicit filter pick MUST match the id — legacy rows
      // predating the P4 taxonomy naturally drop out here.
      vis = vis.filter(
        (r) => r.service_category_id === serviceCategoryFilter,
      );
    }
    return vis;
  }, [items, searchQuery, serviceCategoryFilter]);

  const load = async () => {
    setLoading(true);
    try {
      const [tpls, custs, techsRes, crewsRes] = await Promise.all([
        // Phase P18 · Feb-2026 — pass the ``status`` filter so the
        // backend narrows the row set BEFORE returning; counts still
        // reflect the tenant-wide totals via the aggregate.
        api.get(`/recurring-jobs?status=${encodeURIComponent(statusTab)}`),
        api.get("/customers?is_active=true&limit=500").catch(() => ({ items: [] })),
        api.get("/technicians").catch(() => []),
        // Phase H9 · Feb-2026 — crews. Same 403-safe pattern.
        api.get("/crews").catch(() => ({ items: [] })),
      ]);
      setItems(tpls?.items || []);
      // Phase P18 · Feb-2026 — the response now carries ``counts:
      // {active, paused, total}`` (backend aggregate). Legacy consumers
      // still see ``items`` + ``count`` unchanged.
      if (tpls?.counts && typeof tpls.counts === "object") {
        setTabCounts({
          active: Number(tpls.counts.active || 0),
          paused: Number(tpls.counts.paused || 0),
          total: Number(tpls.counts.total || 0),
        });
      }
      setCustomers(Array.isArray(custs) ? custs : (custs?.items || []));
      setTechs(Array.isArray(techsRes) ? techsRes : (techsRes?.items || []));
      setCrews(Array.isArray(crewsRes) ? crewsRes : (crewsRes?.items || []));
    } catch (e) {
      setError(e?.message || "Failed to load");
    } finally { setLoading(false); }
    // Feb-2026 P0 · Fire an orphan-preview scan right after the main
    // load. Best-effort — a failure just leaves the banner hidden.
    try {
      const preview = await api.get("/recurring-jobs/orphans");
      setOrphanPreview(preview);
    } catch (_e) {
      setOrphanPreview(null);
    }
    // Phase P14 · Feb-2026 · Item 2 — parallel purge-preview scan.
    // Same shape as the backfill preview above: best-effort, a
    // failure leaves the purge button hidden.
    try {
      const p14 = await api.get("/recurring-jobs/purge-orphans-preview");
      setPurgePreview(p14);
    } catch (_e) {
      setPurgePreview(null);
    }
  };

  // Phase P14 · Feb-2026 · Item 2 — purge orphans. Fires only after
  // the operator types ``DELETE`` in the confirm dialog (client
  // gate) AND the backend re-checks the same string as its own
  // gate on the POST. On success we refresh both the main table
  // and the two preview scans so the banner disappears cleanly.
  const runPurgeOrphans = async () => {
    if ((purgeInput || "").trim() !== "DELETE") return;
    setPurgeBusy(true);
    try {
      const res = await api.post(
        "/recurring-jobs/purge-orphans",
        { confirm: "DELETE" },
      );
      setPurgeConfirmOpen(false);
      setPurgeInput("");
      // Refresh the whole surface — banner recomputes off fresh
      // preview scans, table drops the deleted rows.
      await load();
      // eslint-disable-next-line no-alert
      window.alert(
        `Purged ${res?.deleted_count ?? 0} orphaned recurring `
        + `job${(res?.deleted_count ?? 0) === 1 ? "" : "s"}.`
      );
    } catch (e) {
      setError(e?.message || "Purge failed");
    } finally {
      setPurgeBusy(false);
    }
  };

  const runBackfill = async () => {
    // eslint-disable-next-line no-alert
    const ok = window.confirm(
      `Create ${orphanPreview?.orphan_count || 0} missing recurring-job templates for ` +
      `${orphanPreview?.total_occurrences || 0} orphan occurrences?\n\n` +
      `This is idempotent — existing templates stay untouched.`
    );
    if (!ok) return;
    setOrphanBusy(true);
    try {
      const res = await api.post("/recurring-jobs/backfill-orphans", {});
      // Refresh both the main table and the orphan preview.
      await load();
      // eslint-disable-next-line no-alert
      window.alert(
        `Backfill complete.\n\n` +
        `Created: ${res?.created ?? 0}\n` +
        `Skipped (already existed): ${res?.skipped_existing ?? 0}`
      );
    } catch (e) {
      setError(e?.message || "Backfill failed");
    } finally {
      setOrphanBusy(false);
    }
  };

  useEffect(() => { load(); }, []);

  // Phase P18 · Feb-2026 — refetch whenever the tab changes AND
  // sync the ``?status=`` URL param so refresh / deep links land on
  // the right tab. Search state (searchInput / searchQuery) is
  // preserved by React state across the refetch; the URL param is
  // the single source of truth for the selected tab.
  useEffect(() => {
    const currentParam = (searchParams.get("status") || "").toLowerCase();
    if (currentParam !== statusTab) {
      const next = new URLSearchParams(searchParams);
      next.set("status", statusTab);
      setSearchParams(next, { replace: true });
    }
    load();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [statusTab]);

  // Phase P3 · Feb-2026 — Escape closes the Edit / Create modal.
  // Attached only while ``modalOpen`` is true so we don't fight
  // other keyboard consumers on the page (e.g. the bulk-delete
  // modal's own dismiss button).
  useEffect(() => {
    if (!modalOpen) return;
    const onKey = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        setModalOpen(false);
        setEditing(null);
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [modalOpen]);

  // Phase P4 · Feb-2026 — Category taxonomy fetch. Runs whenever
  // the Edit modal opens.  ``Promise.allSettled`` so a failure on
  // one endpoint doesn't hide the other dropdown — the user still
  // gets to edit the field that DID load.
  const _loadCategories = React.useCallback(async () => {
    setCatLoading(true);
    setCatLoadErr({ service: false, income: false });
    const [svcRes, incRes] = await Promise.allSettled([
      api.get("/service-categories"),
      api.get("/income-categories"),
    ]);
    if (svcRes.status === "fulfilled") {
      setServiceCats(
        (svcRes.value?.items || []).filter((c) => !c.is_archived),
      );
    } else {
      setServiceCats([]);
      setCatLoadErr((x) => ({ ...x, service: true }));
    }
    if (incRes.status === "fulfilled") {
      setIncomeCats(
        (incRes.value?.items || []).filter((c) => !c.is_archived),
      );
    } else {
      setIncomeCats([]);
      setCatLoadErr((x) => ({ ...x, income: true }));
    }
    setCatLoading(false);
  }, []);

  useEffect(() => {
    if (!modalOpen) return;
    setCatSaveErr({ service: "", income: "" });
    _loadCategories();
  }, [modalOpen, _loadCategories]);

  // Phase P54 · Feb-2026 — Category taxonomy also loads on MOUNT
  // so the service-category filter dropdown at the top of the
  // page + the "Bulk Edit Categories" modal have their options
  // populated before the user ever opens the row-Edit modal.
  // Fires once per mount; the Edit-modal effect above still
  // re-fetches on every modal open for freshness.
  useEffect(() => {
    _loadCategories();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  // Phase P3 · Feb-2026 — `stopThen` wraps existing per-row
  // action buttons so their onClick doesn't bubble up to the
  // <tr>'s row-click handler and open the Edit modal too. The
  // wrapped function is called AFTER the event's propagation
  // is stopped, preserving the original semantics.
  const stopThen = (fn) => (e) => {
    if (e && typeof e.stopPropagation === "function") {
      e.stopPropagation();
    }
    return fn();
  };

  const openCreate = () => {
    setEditing({ frequency: "weekly", day_of_week: 0, start_date: todayIso(), price_cents: 12000, active: true, is_active: false, notes: "", recurrence_never_ends: true, end_date: null });
    setPriceStr("120.00");
    setPriceErr("");
    // Phase P33 · Reset property state on modal open — the ref
    // guards against a stale customer's property list surviving
    // between modal sessions.
    setCustomerProperties([]);
    previousModalCustomerRef.current = null;
    setModalOpen(true);
  };
  const openEdit = (row) => {
    // Feb-2026 · Ends-mode default. Legacy rows may have neither
    // `recurrence_never_ends` nor `end_date`; treat that as "Never"
    // per the product rule ("if neither set, fall back to Never").
    const neverEnds = row.recurrence_never_ends === true
      || (row.recurrence_never_ends == null && !row.end_date);
    setEditing({ ...row, recurrence_never_ends: neverEnds });
    setPriceStr(((row.price_cents || 0) / 100).toFixed(2));
    setPriceErr("");
    // Phase P33 · Reset property list and force a refetch by
    // clearing the previous-customer sentinel. The effect below
    // sees the state transition (null → row.customer_id) and
    // hydrates.
    setCustomerProperties([]);
    previousModalCustomerRef.current = null;
    setModalOpen(true);
  };

  // Phase P33 · Feb-2026 — Fetch active properties for the modal's
  // selected customer. Mirrors the JobNew.jsx pattern (see
  // ``frontend/src/pages/jobs/JobNew.jsx`` lines 155-191): every
  // customer switch invalidates the previous ``property_id`` so a
  // stale pick from the outgoing customer can't leak into the new
  // payload. Auto-select fires ONLY in the 1-property case;
  // multi-property customers get a required <select>.
  useEffect(() => {
    if (!modalOpen || !editing) {
      setCustomerProperties([]);
      previousModalCustomerRef.current = null;
      return;
    }
    const cid = editing.customer_id || "";
    // Detect a customer switch (vs. initial hydrate on modal open
    // where the ref is null). On switch, null the property_id
    // BEFORE the fetch so the 0/1/2+ auto-select re-runs cleanly.
    if (previousModalCustomerRef.current !== null
        && previousModalCustomerRef.current !== cid) {
      setEditing((x) => (x ? { ...x, property_id: null } : x));
    }
    previousModalCustomerRef.current = cid;
    if (!cid) {
      setCustomerProperties([]);
      return;
    }
    let cancelled = false;
    setPropsLoading(true);
    api.get(`/customers/${cid}/properties`)
      .then((rows) => {
        if (cancelled) return;
        const active = (Array.isArray(rows) ? rows : [])
          .filter((r) => r && r.active !== false);
        setCustomerProperties(active);
        // Auto-fill on the 1-property case so the save can proceed
        // without a click. Preserve an existing property_id only
        // when the new customer actually owns it (edit-mode
        // hydration of an already-set property_id).
        setEditing((x) => {
          if (!x) return x;
          if (x.property_id
              && active.some((p) => p.id === x.property_id)) {
            return x;
          }
          if (active.length === 1) {
            return { ...x, property_id: active[0].id };
          }
          return { ...x, property_id: null };
        });
      })
      .catch(() => {
        if (!cancelled) setCustomerProperties([]);
      })
      .finally(() => {
        if (!cancelled) setPropsLoading(false);
      });
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [modalOpen, editing?.customer_id]);

  // Phase P33 · Feb-2026 — Save-gate flag derived from the
  // property-selector state. ``true`` means the current
  // (customer, property) pair is well-formed enough to save:
  //   * No customer picked yet → true (the customer-required gate
  //     on Save already blocks this — this hook doesn't
  //     double-gate).
  //   * Customer picked, 0 properties → false (Save disabled with
  //     "no addresses on file" warning).
  //   * Customer picked, 1 property → true (auto-selected).
  //   * Customer picked, 2+ properties, property_id set → true.
  //   * Customer picked, 2+ properties, property_id unset → false.
  const propertyGateOk = (() => {
    if (!editing?.customer_id) return true;
    if (propsLoading) return true;   // don't disable while loading
    if (customerProperties.length === 0) return false;
    if (customerProperties.length === 1) return true;
    return !!editing.property_id;
  })();

  // Phase H9 · Feb-2026 — Accept optional leading "$", 0-5 digit
  // integer part, optional decimal with up to 2 fraction digits.
  // Empty string counts as invalid so the caller can't accidentally
  // silently blank the price.
  const _PRICE_RE = /^\$?\d{1,5}(\.\d{0,2})?$/;
  const _validatePrice = (s) => {
    const trimmed = (s || "").trim();
    if (!trimmed) return false;
    if (!_PRICE_RE.test(trimmed)) return false;
    const n = Number(trimmed.replace("$", ""));
    if (!Number.isFinite(n)) return false;
    if (n < 0 || n > 99999.99) return false;
    return true;
  };

  const save = async () => {
    setError(null);
    // Phase H9 · Feb-2026 — validate the free-text price. UI's
    // save button is disabled while ``priceErr`` is non-empty
    // but we defense-in-depth here too.
    if (!_validatePrice(priceStr)) {
      setPriceErr("Enter a valid price (0.00 – 99999.99)");
      return;
    }
    try {
      const priceCents = Math.round(
        Number(priceStr.replace("$", "")) * 100,
      );
      // Feb-2026 · Never-end recurrence · UI intent maps to backend
      // flag. When true, clear the end_date field client-side too so
      // the payload doesn't fight the backend override.
      const payload = { ...editing, price_cents: priceCents };
      if (payload.recurrence_never_ends) payload.end_date = null;
      // Phase P4 · Feb-2026 — Category taxonomy on save.
      // The two ids are pulled straight off ``editing`` so an
      // "— None —" pick (which sets the field to "") gets
      // sent as explicit ``null`` for a server-side clear.
      // A key that is absent → no change, exactly per the P4
      // brief.  We compare to the string "" to distinguish an
      // explicit clear from an untouched field.
      if (Object.prototype.hasOwnProperty.call(editing, "service_category_id")) {
        payload.service_category_id = editing.service_category_id === "" ?
          null : editing.service_category_id;
      }
      if (Object.prototype.hasOwnProperty.call(editing, "income_category_id")) {
        payload.income_category_id = editing.income_category_id === "" ?
          null : editing.income_category_id;
      }
      if (editing.id) {
        await api.patch(`/recurring-jobs/${editing.id}`, payload);
      } else {
        // Feb-2026 · Phase — Recommended Schedule auto-assign v1.
        // Backend returns ``auto_assign_info`` on create so we can
        // pick the toast variant without a second round-trip.
        const created = await api.post("/recurring-jobs", payload);
        const info = created?.auto_assign_info || {};
        if (info.auto_assigned) {
          const dowName = DOW[info.day_of_week] || "the assigned day";
          toast.success(
            `Assigned to ${info.technician_name || "a technician"} ` +
            `on ${dowName} based on route proximity`,
            { duration: 4500 },
          );
        } else if (info.reason === "no_geocode") {
          toast(
            "Created — no coordinates on customer, please assign manually",
            { duration: 4500 },
          );
        } else if (info.reason === "no_existing_routes") {
          toast(
            "Created without auto-assign — no existing routes for this frequency yet",
            { duration: 4500 },
          );
        }
        // ``manual_override`` and any other reason → no extra toast;
        // the create itself is the confirmation.
      }
      setModalOpen(false); setEditing(null);
      await load();
    } catch (e) {
      // Phase P4 · Feb-2026 — 422 with the category-invalid code
      // renders a per-field error next to the offending dropdown
      // and keeps the modal open so the user can fix it without
      // re-entering every other field.
      //
      // The api client throws with the response body stashed on
      // ``e.body`` (or ``e.response.data``).  We accept either
      // ``detail.code`` OR a naked ``code`` at the top level to
      // keep this resilient to future adapter tweaks.
      const raw = (e && (e.body || e.response?.data)) || {};
      const detail = raw.detail || raw;
      const status = e && (e.status || e.response?.status);
      if (status === 422 && detail && detail.code) {
        if (detail.code === "service_category_invalid") {
          setCatSaveErr((x) => ({ ...x, service: "Invalid — pick another" }));
          return;
        }
        if (detail.code === "income_category_invalid") {
          setCatSaveErr((x) => ({ ...x, income: "Invalid — pick another" }));
          return;
        }
      }
      setError(e?.message || "Save failed");
    }
  };

  const togglePause = async (row) => {
    setBusy(row.id);
    try {
      // Phase P18 · Feb-2026 — send both ``is_active`` (canonical)
      // AND ``active`` (legacy mirror) so the backend PATCH detects
      // the True→False transition and fires the auto-cancel side-
      // effect.  When pausing, we surface the cancelled_visit_count
      // in a toast.  Resume (False→True) fires inline generation
      // via the pre-existing Auto-Activate path.
      const effectiveActive = row.is_active !== undefined
        ? !!row.is_active : !!row.active;
      const nextActive = !effectiveActive;
      const res = await api.patch(`/recurring-jobs/${row.id}`, {
        is_active: nextActive,
        active: nextActive,
      });
      if (!nextActive) {
        // Pause path — announce how many future visits were cancelled.
        const n = Number(res?.cancelled_visit_count || 0);
        const noun = n === 1 ? "visit" : "visits";
        toast.success(`Paused. ${n} future ${noun} cancelled.`);
      } else {
        toast.success("Resumed.");
      }
      await load();
    } catch (e) {
      toast.error(e?.message || "Save failed");
    } finally { setBusy(null); }
  };

  const softDelete = async (row) => {
    setBusy(row.id);
    try { await api.del(`/recurring-jobs/${row.id}`); await load(); }
    finally { setBusy(null); }
  };

  const hardDelete = async (row) => {
    // Feb-2026 · Recurring Jobs · HARD delete. Backend removes the
    // template row + cancels every future-scheduled child job.
    // Completed / in-progress children are preserved.
    setBusy(row.id);
    try {
      await api.del(`/recurring-jobs/${row.id}?hard=true`);
      // Phase P3 · Feb-2026 — if the row being deleted is
      // currently open in the Edit modal, close it gracefully
      // so the modal never renders against a stale `editing`.
      if (editing && editing.id === row.id) {
        setModalOpen(false);
        setEditing(null);
      }
      setHardDeleteTarget(null);
      await load();
    } finally { setBusy(null); }
  };

  // Phase R1 · Feb-2026 — Bulk Hard Delete.
  //
  // Posts every selected template id to
  // ``POST /api/recurring-jobs/bulk-delete``.  The backend returns
  // HTTP 200 even on partial failures with a summary + per-id
  // status list, so the toast reflects the TRUTH — "Deleted 3 of 3"
  // vs "Deleted 2 of 3; 1 failed — see log".  On any per-id error
  // we fire a warning-style toast, never a success.
  const bulkHardDelete = async () => {
    if (selectedIds.size === 0) return;
    if (!bulkAcked) return;
    setBulkBusy(true);
    try {
      const ids = Array.from(selectedIds);
      const res = await api.post("/recurring-jobs/bulk-delete", {
        recurring_job_ids: ids,
      });
      const summary = res?.summary || {};
      const deleted = Number(summary.templates_deleted || 0);
      const visits = Number(summary.future_visits_deleted || 0);
      const errs = Number(summary.errors || 0);
      const total = ids.length;
      if (errs === 0) {
        toast.success(
          `Deleted ${deleted} template${deleted === 1 ? "" : "s"}` +
          ` and ${visits} future visit${visits === 1 ? "" : "s"}.`,
        );
      } else {
        toast.warning(
          `Deleted ${deleted} of ${total}; ${errs} failed — see log.`,
        );
      }
      setSelectedIds(new Set());
      setBulkModalOpen(false);
      setBulkAcked(false);
      await load();
    } catch (e) {
      toast.error(e?.message || "Bulk delete failed");
    } finally {
      setBulkBusy(false);
    }
  };

  // Feb-2026 · P1 Auto-Activate + Bulk Activate + Instant Generation.
  //
  // Posts every selected template id to
  // ``POST /api/recurring-jobs/bulk-activate``.  The backend returns
  // HTTP 200 with per-id status rows + aggregate counts. The batch
  // cap is 100 — we slice payloads > 100 in place so the operator
  // never sees a raw 400 ``batch_too_large`` error. Toast reflects
  // the truth: activated / already-active / failed / total newly-
  // generated visits + a "skipped (missing start date)" note when
  // that condition applies to any row.
  const BULK_ACTIVATE_BATCH = 100;
  const bulkActivate = async () => {
    if (selectedIds.size === 0) return;
    if (bulkActivateBusy) return;
    setBulkActivateBusy(true);
    try {
      const allIds = Array.from(selectedIds);
      let activated = 0;
      let already_active = 0;
      let failed = 0;
      let generated = 0;
      let skippedNoStart = 0;
      for (let i = 0; i < allIds.length; i += BULK_ACTIVATE_BATCH) {
        const slice = allIds.slice(i, i + BULK_ACTIVATE_BATCH);
        // eslint-disable-next-line no-await-in-loop
        const res = await api.post("/recurring-jobs/bulk-activate", {
          recurring_job_ids: slice,
        });
        activated += Number(res?.activated || 0);
        already_active += Number(res?.already_active || 0);
        failed += Number(res?.failed || 0);
        for (const row of res?.results || []) {
          generated += Number(row?.generated_count || 0);
          if (row?.skipped_no_start_date) skippedNoStart += 1;
        }
      }
      const parts = [];
      parts.push(`${activated} activated`);
      if (already_active > 0) parts.push(`${already_active} already active`);
      if (failed > 0) parts.push(`${failed} failed`);
      const tail = skippedNoStart > 0
        ? ` · ${skippedNoStart} skipped (missing start date)`
        : "";
      const line = `${parts.join(", ")} · ${generated} visit${
        generated === 1 ? "" : "s"} generated${tail}`;
      if (failed > 0) {
        toast.warning(line);
      } else {
        toast.success(line);
      }
      setSelectedIds(new Set());
      await load();
    } catch (e) {
      toast.error(e?.message || "Bulk activate failed");
    } finally {
      setBulkActivateBusy(false);
    }
  };

  // Phase P54 · Feb-2026 — Bulk Edit Categories.
  //
  // Posts every selected template id to
  // ``POST /api/recurring-jobs/bulk-update-categories``.  Payload
  // includes ONLY dropdowns the user changed away from
  // "Unchanged" — empty-string sentinels are omitted so the
  // backend's ``model_fields_set`` check keeps them out of the
  // write set.
  //
  // Batch cap: 100 (backend constant ``_BULK_UPDATE_CATEGORIES_
  // MAX``).  Payloads > 100 are sliced in place so the operator
  // never sees a raw 400.  Aggregate counts across slices drive
  // the toast.
  const BULK_UPDATE_CATEGORIES_BATCH = 100;
  const bulkEditApply = async () => {
    if (selectedIds.size === 0) return;
    if (bulkEditBusy) return;
    // Guard against submit with both dropdowns still "Unchanged"
    // — matches the backend's payload-level 400 but we short-circuit
    // client-side so the user never sees a raw error toast.
    if (!bulkEditServiceCat && !bulkEditIncomeCat) {
      setBulkEditError(
        "Pick at least one category to apply before Apply.",
      );
      return;
    }
    setBulkEditError("");
    setBulkEditBusy(true);
    try {
      const allIds = Array.from(selectedIds);
      let updated = 0;
      let already = 0;
      let failed = 0;
      let childInv = 0;
      for (let i = 0; i < allIds.length; i += BULK_UPDATE_CATEGORIES_BATCH) {
        const slice = allIds.slice(i, i + BULK_UPDATE_CATEGORIES_BATCH);
        const payload = { ids: slice };
        // Only include dropdowns the user changed. "Unchanged"
        // (empty string) MUST NOT be sent — the backend distinguishes
        // JSON-absent from JSON-null via ``model_fields_set``.
        if (bulkEditServiceCat) {
          payload.service_category_id = bulkEditServiceCat;
        }
        if (bulkEditIncomeCat) {
          payload.income_category_id = bulkEditIncomeCat;
        }
        // eslint-disable-next-line no-await-in-loop
        const res = await api.post(
          "/recurring-jobs/bulk-update-categories", payload,
        );
        updated += Number(res?.updated || 0);
        already += Number(res?.already_current || 0);
        failed += Number(res?.failed || 0);
        childInv += Number(
          res?.sync_result_summary?.child_invoices_updated || 0,
        );
      }
      const parts = [`${updated} updated`];
      if (already > 0) parts.push(`${already} already current`);
      if (failed > 0) parts.push(`${failed} failed`);
      const tail = childInv > 0
        ? ` · ${childInv} invoice${childInv === 1 ? "" : "s"} synced`
        : "";
      const line = `${parts.join(", ")}${tail}`;
      if (failed > 0) {
        toast.warning(line);
      } else {
        toast.success(line);
      }
      setSelectedIds(new Set());
      setBulkEditOpen(false);
      setBulkEditServiceCat("");
      setBulkEditIncomeCat("");
      await load();
    } catch (e) {
      // Backend payload-level 422s carry {code, field, attempted,
      // collection}.  Render the code inline so the user sees the
      // specific failure instead of a generic toast.
      const raw = e?.response?.data?.detail || e?.data?.detail || e?.detail;
      if (raw && typeof raw === "object" && raw.code) {
        setBulkEditError(
          `${raw.code}${raw.field ? ` (${raw.field})` : ""}`,
        );
      } else if (raw && typeof raw === "object" && raw.error) {
        setBulkEditError(String(raw.error));
      } else {
        toast.error(e?.message || "Bulk edit failed");
      }
    } finally {
      setBulkEditBusy(false);
    }
  };

  // Header "select all on page" checkbox.  Respects the R2 client-
  // side search filter — bulk-select on page = every row currently
  // visible under the active search query.
  const _visibleIds = () => filteredItems.map((r) => r.id);
  const _allVisibleSelected = () => {
    const vis = _visibleIds();
    return vis.length > 0 && vis.every((id) => selectedIds.has(id));
  };
  const _someVisibleSelected = () => {
    const vis = _visibleIds();
    return vis.some((id) => selectedIds.has(id));
  };
  const _toggleAllVisible = () => {
    if (_allVisibleSelected()) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(_visibleIds()));
    }
  };
  const _toggleOne = (id) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const stopRecurrence = async (row) => {
    // Feb-2026 · Never-end recurrence · Stop action. Confirm because
    // this removes unstarted future occurrences from db.jobs.
    // eslint-disable-next-line no-alert
    const ok = window.confirm(
      "Stop generating future occurrences?\n\nExisting scheduled visits from today onward that haven't been started will be removed. Started/completed visits and today's route stay untouched."
    );
    if (!ok) return;
    setBusy(row.id);
    try {
      const res = await api.post(`/recurring-jobs/${row.id}/stop`, {});
      alertOk(`Stopped. Removed ${res?.removed_future_jobs ?? 0} future occurrences.`);
      await load();
    } catch (e) {
      setError(e?.message || "Stop failed");
    } finally {
      setBusy(null);
    }
  };

  const generateNow = async (row) => {
    setBusy(row.id);
    try {
      const through = addDaysIso(todayIso(), 14);
      const res = await api.post(`/recurring-jobs/${row.id}/generate?through=${through}`, {});
      alertOk(`Generated ${res?.inserted || 0} jobs (skipped ${res?.skipped || 0}).`);
      await load();
    } catch (e) { setError(e?.message || "Generate failed"); }
    finally { setBusy(null); }
  };

  const alertOk = (msg) => { setError(null); setBusy(null); window.setTimeout(() => setError(null), 100); /* mini-toast substitute */ setError(msg); setTimeout(() => setError(null), 2500); };

  return (
    <div className="p-4 md:p-8 max-w-6xl mx-auto" data-testid="recurring-jobs-page">
      <div className="flex items-start md:items-center flex-col md:flex-row md:justify-between gap-3 mb-6">
        <div className="flex items-center gap-3">
          <div className="w-11 h-11 rounded-xl flex items-center justify-center"
               style={{ backgroundColor: colors.brandTertiary, color: colors.onBrandTertiary }}>
            <CalendarClock size={20} />
          </div>
          <div>
            <h1 className="text-2xl md:text-3xl font-bold" style={{ color: colors.onSurface }}>Recurring Jobs</h1>
            <p className="text-sm mt-0.5" style={{ color: colors.muted }}>
              Auto-generates a rolling 2-week horizon of jobs. Nightly cron @ 02:00 UTC.
            </p>
          </div>
        </div>
        <button type="button" onClick={openCreate}
                className="inline-flex items-center gap-1 text-sm font-bold px-3 py-2 rounded-md"
                style={{ background: colors.brand, color: "#fff", border: 0 }}
                data-testid="recurring-jobs-create">
          <Plus size={14} /> New recurring job
        </button>
        {/* Feb-2026 · P1 Auto-Activate + Bulk Activate — green
             toolbar button that flips ``is_active=True`` on every
             selected template AND fires the 14-day inline generator
             so operators see near-term visits without waiting for
             the nightly cron. Sits immediately BEFORE the
             destructive "Delete permanently" button; both share the
             same disabled-when-empty visual language. */}
        <button
          type="button"
          onClick={bulkActivate}
          disabled={selectedIds.size === 0 || bulkActivateBusy}
          className="inline-flex items-center gap-1 text-sm font-bold px-3 py-2 rounded-md ml-2"
          style={{
            background: selectedIds.size === 0 ? "#DCFCE7" : "#059669",
            color: selectedIds.size === 0 ? "#065F46" : "#FFFFFF",
            border: 0,
            opacity: (selectedIds.size === 0 || bulkActivateBusy) ? 0.5 : 1,
            cursor: (selectedIds.size === 0 || bulkActivateBusy)
              ? "not-allowed" : "pointer",
          }}
          aria-disabled={selectedIds.size === 0 || bulkActivateBusy}
          data-testid="recurring-bulk-activate"
        >
          <Play size={14} />{" "}
          {bulkActivateBusy ? "Activating…" :
            `Bulk Activate${selectedIds.size > 0 ? ` (${selectedIds.size})` : ""}`}
        </button>
        {/* Phase P54 · Feb-2026 — Bulk Edit Categories toolbar
             button. Sits between the green "Bulk Activate" and
             the destructive red "Delete permanently" — neutral
             indigo affordance so it visually reads as an
             *editing* action, not activating or destroying.
             Always rendered so testid is queryable; disabled +
             semi-opaque when no rows are checked. */}
        <button
          type="button"
          onClick={() => {
            setBulkEditServiceCat("");
            setBulkEditIncomeCat("");
            setBulkEditError("");
            setBulkEditOpen(true);
          }}
          disabled={selectedIds.size === 0 || bulkEditBusy}
          className="inline-flex items-center gap-1 text-sm font-bold px-3 py-2 rounded-md ml-2"
          style={{
            background: selectedIds.size === 0 ? "#E0E7FF" : "#4F46E5",
            color: selectedIds.size === 0 ? "#3730A3" : "#FFFFFF",
            border: 0,
            opacity: (selectedIds.size === 0 || bulkEditBusy) ? 0.5 : 1,
            cursor: (selectedIds.size === 0 || bulkEditBusy)
              ? "not-allowed" : "pointer",
          }}
          aria-disabled={selectedIds.size === 0 || bulkEditBusy}
          data-testid="recurring-bulk-edit-categories"
        >
          <Tag size={14} />{" "}
          {bulkEditBusy ? "Applying…" :
            `Bulk Edit Categories${selectedIds.size > 0 ? ` (${selectedIds.size})` : ""}`}
        </button>
        {/* Phase R1 · Feb-2026 — bulk hard-delete toolbar button.
             Always rendered so its testid is queryable by unit
             tests + Playwright; disabled when nothing is
             selected. The label appends the running count so
             ops always sees ``Delete permanently (N)`` — the
             count comes from the visible-page checkbox state,
             not the server. */}
        <button
          type="button"
          onClick={() => { setBulkAcked(false); setBulkModalOpen(true); }}
          disabled={selectedIds.size === 0}
          className="inline-flex items-center gap-1 text-sm font-bold px-3 py-2 rounded-md ml-2"
          style={{
            background: selectedIds.size === 0 ? "#FEE2E2" : "#B91C1C",
            color: selectedIds.size === 0 ? "#B91C1C" : "#FFFFFF",
            border: 0,
            opacity: selectedIds.size === 0 ? 0.5 : 1,
            cursor: selectedIds.size === 0 ? "not-allowed" : "pointer",
          }}
          aria-disabled={selectedIds.size === 0}
          data-testid="recurring-bulk-hard-delete"
        >
          <Trash2 size={14} />{" "}
          Delete permanently{selectedIds.size > 0 ? ` (${selectedIds.size})` : ""}
        </button>
      </div>

      {error ? (
        <div className="rounded-2xl p-3 mb-4 text-sm"
             style={{ background: "#FEF2F2", border: "1px solid #FECACA", color: "#B91C1C" }}
             data-testid="recurring-jobs-error">{error}</div>
      ) : null}

      {/* Feb-2026 P0 · Orphan cluster banner. Renders only when the
          orphan-preview scan found at least one cluster missing a
          matching template. Operator can click "Backfill now" to
          mint them; idempotent so re-running is safe.

          Phase P14 · Feb-2026 · Item 2 — same yellow banner
          container now ALSO carries a red "Delete all orphans
          permanently" button when the purge-preview scan found
          templates whose ``customer_id`` doesn't resolve. Banner
          renders when EITHER preview is non-zero so the operator
          sees whichever remediation applies. */}
      {(orphanPreview && orphanPreview.orphan_count > 0)
       || (purgePreview && purgePreview.count > 0) ? (
        <div
          className="rounded-2xl p-4 mb-4 text-sm flex items-start justify-between gap-3"
          style={{ background: "#FEF3C7", border: "1px solid #FCD34D",
                    color: "#78350F" }}
          data-testid="recurring-jobs-orphan-banner"
        >
          <div>
            {orphanPreview && orphanPreview.orphan_count > 0 ? (
              <>
                <div className="font-bold">
                  {orphanPreview.orphan_count} recurring customer
                  {orphanPreview.orphan_count === 1 ? "" : "s"} missing from this list.
                </div>
                <div className="mt-0.5 text-xs">
                  Detected {orphanPreview.total_occurrences} pre-scheduled visits from
                  the Schedule page that have no matching recurring template. Click
                  &ldquo;Backfill now&rdquo; to add them here — existing entries won&rsquo;t be touched.
                </div>
              </>
            ) : null}
            {purgePreview && purgePreview.count > 0 ? (
              <div
                className={orphanPreview && orphanPreview.orphan_count > 0 ? "mt-2" : ""}
                data-testid="recurring-jobs-purge-summary"
              >
                <div className="font-bold">
                  {purgePreview.count} orphaned recurring
                  job{purgePreview.count === 1 ? "" : "s"} with a deleted customer.
                </div>
                <div className="mt-0.5 text-xs">
                  These templates point at a ``customer_id`` that no longer
                  resolves in this tenant — safe to delete permanently.
                </div>
              </div>
            ) : null}
          </div>
          <div className="flex flex-col gap-2 shrink-0">
            {orphanPreview && orphanPreview.orphan_count > 0 ? (
              <button
                type="button"
                onClick={runBackfill}
                disabled={orphanBusy}
                className="inline-flex items-center gap-1 text-xs font-bold px-3 py-2 rounded-md whitespace-nowrap"
                style={{ background: "#B45309", color: "#FFFFFF", border: 0,
                          opacity: orphanBusy ? 0.5 : 1 }}
                data-testid="recurring-jobs-backfill-btn"
              >
                {orphanBusy ? "Backfilling…" : "Backfill now"}
              </button>
            ) : null}
            {purgePreview && purgePreview.count > 0 ? (
              <button
                type="button"
                onClick={() => { setPurgeInput(""); setPurgeConfirmOpen(true); }}
                disabled={purgeBusy}
                className="inline-flex items-center gap-1 text-xs font-bold px-3 py-2 rounded-md whitespace-nowrap"
                style={{ background: "#B91C1C", color: "#FFFFFF", border: 0,
                          opacity: purgeBusy ? 0.5 : 1 }}
                data-testid="recurring-jobs-purge-btn"
              >
                {purgeBusy
                  ? "Deleting…"
                  : `Delete all orphans permanently (${purgePreview.count})`}
              </button>
            ) : null}
          </div>
        </div>
      ) : null}

      {/* Phase P14 · Feb-2026 · Item 2 — purge confirm dialog.
          Requires the operator to type ``DELETE`` verbatim. Same
          shadcn ``Dialog`` primitive the rest of the page's
          destructive flows use, kept intentionally minimal so it
          fits inside the existing dialog stack without z-index
          fights. */}
      {purgeConfirmOpen ? (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center"
          style={{ background: "rgba(15,23,42,0.55)" }}
          data-testid="recurring-jobs-purge-confirm"
        >
          <div
            className="w-full max-w-md rounded-2xl p-5 space-y-3"
            style={{ background: colors.surface, border: `1px solid ${colors.border}` }}
          >
            <h2 className="text-lg font-bold" style={{ color: colors.onSurface }}>
              Delete orphaned recurring jobs?
            </h2>
            <p className="text-sm" style={{ color: colors.muted }}>
              This will permanently delete{" "}
              <b>{purgePreview?.count || 0}</b>{" "}
              orphaned recurring job{(purgePreview?.count || 0) === 1 ? "" : "s"}.
              This cannot be undone.
            </p>
            <label className="text-xs font-semibold block" style={{ color: colors.muted }}>
              Type DELETE to confirm
              <input
                type="text"
                value={purgeInput}
                onChange={(e) => setPurgeInput(e.target.value)}
                className="w-full mt-1 px-2 py-1.5 rounded text-sm"
                style={{
                  border: `1px solid ${colors.border}`,
                  background: colors.surface,
                  color: colors.onSurface,
                }}
                data-testid="recurring-jobs-purge-input"
                autoFocus
              />
            </label>
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={() => { setPurgeConfirmOpen(false); setPurgeInput(""); }}
                disabled={purgeBusy}
                className="px-3 py-1.5 rounded-md text-sm"
                style={{ border: `1px solid ${colors.border}`, background: colors.surface, color: colors.onSurface }}
                data-testid="recurring-jobs-purge-cancel"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={runPurgeOrphans}
                disabled={purgeBusy || (purgeInput || "").trim() !== "DELETE"}
                className="px-3 py-1.5 rounded-md text-sm font-bold"
                style={{
                  background: "#B91C1C", color: "#FFFFFF", border: 0,
                  opacity: (purgeBusy || (purgeInput || "").trim() !== "DELETE") ? 0.5 : 1,
                }}
                data-testid="recurring-jobs-purge-commit"
              >
                {purgeBusy ? "Deleting…" : "Delete permanently"}
              </button>
            </div>
          </div>
        </div>
      ) : null}

      {loading ? (
        <div className="rounded-2xl p-8 text-center text-sm"
             style={{ background: colors.surface, border: `1px solid ${colors.border}`, color: colors.muted }}>
          Loading…
        </div>
      ) : (
        <>
        {/* Phase P18 · Feb-2026 — Active / Paused tab switcher.
             Counts come from the tenant-wide aggregate returned by
             the backend so the badge stays honest even when the
             client-side customer search filter narrows the visible
             row set. URL query ``?status=`` is the source of truth
             for the selected tab. */}
        <div
          className="flex items-center gap-1 mb-4 rounded-xl p-1 w-fit"
          style={{ background: colors.surfaceSecondary,
                    border: `1px solid ${colors.border}` }}
          role="tablist"
          aria-label="Recurring jobs status filter"
          data-testid="recurring-status-tabs"
        >
          {[
            { key: "active", label: "Active" },
            { key: "paused", label: "Paused" },
          ].map((tab) => {
            const isActive = statusTab === tab.key;
            const badge = Number(tabCounts[tab.key] || 0);
            return (
              <button
                key={tab.key}
                type="button"
                role="tab"
                aria-selected={isActive}
                onClick={() => setStatusTab(tab.key)}
                disabled={loading || busy != null}
                className="px-3 py-1.5 text-sm font-semibold rounded-lg transition-colors disabled:opacity-60"
                style={{
                  backgroundColor: isActive ? "#FFFFFF" : "transparent",
                  color: isActive ? colors.onSurface : colors.muted,
                  border: isActive
                    ? `1px solid ${colors.border}`
                    : "1px solid transparent",
                }}
                data-testid={`recurring-status-tab-${tab.key}`}
                data-count={badge}
              >
                {tab.label} ({badge})
              </button>
            );
          })}
        </div>
        {/* Phase R2 · Feb-2026 — customer search.  Client-side
             filter; bulk-select "on page" scopes to filtered rows.
             Phase P54 · Feb-2026 — service-category filter dropdown
             now sits alongside the search input.  Both filters
             AND together (search AND category) and drive the same
             ``filteredItems`` memo so bulk-select "on page" scopes
             to the intersection.

             Task E · Feb-2026 — Bare filter row → NavyFilterBar
             navy chrome. Search input paints solid-white +
             permanent ``#3B82F6`` border + navy text (decision
             #1); service-category select goes navy w/ white text.
             The Clear-X inside the search reuses the legacy
