                            style={{ border: `1px solid #B91C1C`, background: "#B91C1C", color: "#FFFFFF" }}
                            data-testid={`recurring-job-hard-delete-btn-${r.id}`}>
                      <Trash2 size={11} /> Delete permanently
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        </>
