                      Failed to load categories —{" "}
                      <button type="button" className="underline"
                                 onClick={_loadCategories}
                                 data-testid="recurring-jobs-income-category-retry">
                        retry
                      </button>
                    </div>
                  ) : incomeCats.length === 0 ? (
                    <select disabled
